def reimbursable_total(api, trip_id: str) -> dict:
    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    city = trip["city"]
    allowances = policy["allowances_usd"][city]
    rates_by_month = policy["company_rates_usd_per_unit"]

    start_month = trip["start"][:7]
    rates = rates_by_month[start_month]

    receipts = trip["receipts"]

    def to_usd(amount, currency):
        if currency == "USD":
            return float(amount)
        return float(amount) * float(rates[currency])

    meal_by_day = {}
    meal_receipts = []

    for r in receipts:
        note = r.get("note", "")
        if "alcohol" in note.lower():
            continue

        amt_usd = to_usd(r["amount"], r["currency"])
        cat = r["category"]
        day = r["date"]

        if cat == "meal":
            meal_receipts.append((day, amt_usd))
        elif cat == "hotel":
            meal_by_day[day] = meal_by_day.get(day, 0.0)
        elif cat == "taxi":
            if amt_usd > 40.0 and note == "":
                continue
            meal_by_day[day] = meal_by_day.get(day, 0.0)
        else:
            meal_by_day[day] = meal_by_day.get(day, 0.0)

    meal_totals = {}
    for day, amt_usd in meal_receipts:
        meal_totals[day] = meal_totals.get(day, 0.0) + amt_usd

    total = 0.0

    for day, spent in meal_totals.items():
        total += min(spent, float(allowances["meals_per_day"]))

    for r in receipts:
        note = r.get("note", "")
        if "alcohol" in note.lower():
            continue

        amt_usd = to_usd(r["amount"], r["currency"])
        cat = r["category"]

        if cat == "hotel":
            total += min(amt_usd, float(allowances["hotel_per_night"]))
        elif cat == "taxi":
            if amt_usd > 40.0 and note == "":
                continue
            total += amt_usd

    return {"total_usd": round(total + 1e-9, 2)}
