def refund_decision(api, return_id: str) -> dict:
    ret = api.read_return(return_id)
    order = api.read_order(ret["order_id"])
    policy = api.read_policy()
    customer = api.read_customer(order["customer_id"])

    sku = ret["sku"]
    item = None
    for it in order["items"]:
        if it["sku"] == sku:
            item = it
            break

    if item is None:
        return {"method": "decline", "amount_usd": 0}

    delivered_on = order["delivered_on"]
    requested_on = ret["requested_on"]
    category = item["category"]

    def date_parts(s):
        p = s.split("-")
        return int(p[0]), int(p[1]), int(p[2])

    def date_to_ordinal(s):
        y, m, d = date_parts(s)
        leap = 0
        i = 1
        while i < y:
            if i % 4 == 0 and (i % 100 != 0 or i % 400 == 0):
                leap += 1
            i += 1
        mdays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        days = 365 * (y - 1) + leap
        j = 1
        while j < m:
            days += mdays[j - 1]
            if j == 2 and y % 4 == 0 and (y % 100 != 0 or y % 400 == 0):
                days += 1
            j += 1
        days += d
        return days

    def month_day_to_ordinal(y, m, d):
        mdays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        days = 365 * (y - 1)
        leap = 0
        i = 1
        while i < y:
            if i % 4 == 0 and (i % 100 != 0 or i % 400 == 0):
                leap += 1
            i += 1
        days += leap
        j = 1
        while j < m:
            days += mdays[j - 1]
            if j == 2 and y % 4 == 0 and (y % 100 != 0 or y % 400 == 0):
                days += 1
            j += 1
        days += d
        return days

    def date_to_ymd(s):
        p = s.split("-")
        return int(p[0]), int(p[1]), int(p[2])

    delivered_y, delivered_m, delivered_d = date_to_ymd(delivered_on)
    requested_ord = date_to_ordinal(requested_on)
    delivered_ord = date_to_ordinal(delivered_on)

    holiday_window = False
    if delivered_m == 11 and delivered_d >= 15:
        holiday_window = True
    if delivered_m == 12:
        holiday_window = True

    if holiday_window:
        jan31 = month_day_to_ordinal(delivered_y + 1, 1, 31)
        if requested_ord <= jan31:
            amount = item["price"]
            amount = round(amount + 1e-9, 2)
            return {"method": "card", "amount_usd": amount}

    if item["final_sale"]:
        return {"method": "decline", "amount_usd": 0}

    if category == "beauty" and ret["opened"]:
        return {"method": "decline", "amount_usd": 0}

    window_days = policy["return_window_days"][category]
    if customer["tier"] == "plus":
        window_days += policy["member_extra_days"]

    days_since_delivery = requested_ord - delivered_ord

    if days_since_delivery < 0:
        return {"method": "decline", "amount_usd": 0}

    inside_window = days_since_delivery <= window_days
    credit_window = days_since_delivery <= window_days + policy["store_credit_days_after_window"]

    if not inside_window and not credit_window:
        return {"method": "decline", "amount_usd": 0}

    amount = item["price"]

    if ret["missing_accessories"]:
        missing = set()
        for acc in ret["missing_accessories"]:
            missing.add(acc)
        for acc in item["accessories"]:
            if acc["name"] in missing:
                amount -= acc["value"]

    if ret["opened"] and category == "electronics":
        amount -= item["price"] * policy["restocking_fee_opened_electronics"]

    if amount < 0:
        amount = 0

    amount = round(amount + 1e-9, 2)

    if inside_window:
        method = "card"
    else:
        method = "store_credit"

    return {"method": method, "amount_usd": amount}
