def refund_decision(api, return_id):
    ret = api.read_return(return_id)
    order = api.read_order(ret["order_id"])
    policy = api.read_policy()

    customer_id = order["customer_id"]
    customer = api.read_customer(customer_id)
    tier = ""
    if isinstance(customer, dict) and "tier" in customer:
        tier = customer["tier"]

    item = None
    for x in order["items"]:
        if x["sku"] == ret["sku"]:
            item = x
            break

    if item is None:
        return {"method": "decline", "amount_usd": 0}

    reason = ret["reason"]
    opened = bool(ret["opened"])
    missing = ret["missing_accessories"]
    requested_on = ret["requested_on"]
    delivered_on = order["delivered_on"]

    def ymd(s):
        parts = s.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def days_from_civil(y, m, d):
        y = y - 1 if m <= 2 else y
        era = y // 400
        yoe = y - era * 400
        mp = m + 9 if m <= 2 else m - 3
        doy = (153 * mp + 2) // 5 + d - 1
        doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
        return era * 146097 + doe

    req_y, req_m, req_d = ymd(requested_on)
    del_y, del_m, del_d = ymd(delivered_on)
    req_days = days_from_civil(req_y, req_m, req_d)
    del_days = days_from_civil(del_y, del_m, del_d)
    days_since_delivery = req_days - del_days

    category = item["category"]
    window = policy["return_window_days"][category]
    if tier == "plus":
        window = window + policy["member_extra_days"]

    holiday = False
    if del_m == 11 and del_d >= 15:
        holiday = True
    if del_m == 12:
        holiday = True

    is_damaged = False
    reason_lower = str(reason).lower()
    if "damag" in reason_lower or "broken" in reason_lower or "arrived damaged" in reason_lower:
        is_damaged = True

    if item["final_sale"]:
        return {"method": "decline", "amount_usd": 0}

    if category == "beauty" and opened:
        return {"method": "decline", "amount_usd": 0}

    if days_since_delivery < 0:
        return {"method": "decline", "amount_usd": 0}

    if is_damaged and days_since_delivery <= policy["damaged_refund_days"]:
        amount = float(item["price"]) + float(item["shipping"])
        return {"method": "card", "amount_usd": round(amount + 1e-9, 2)}

    if holiday:
        jan_31 = days_from_civil(req_y if req_m == 1 else del_y, 1, 31)
        if req_days <= jan_31:
            amount = float(item["price"])
            if opened and category == "electronics":
                amount = amount * (1 - float(policy["restocking_fee_opened_electronics"]))
            if opened and category == "electronics" and req_days <= jan_31:
                amount = amount
            fee = 0.0
            for acc in item["accessories"]:
                if acc not in missing:
                    pass
            for acc in item["accessories"]:
                if acc in missing:
                    fee = fee + 0.0
            amount = amount - sum([0.0 for acc in missing])  # no accessory values available here
            if amount < 0:
                amount = 0.0
            return {"method": "card", "amount_usd": round(amount + 1e-9, 2)}

    if days_since_delivery <= window:
        amount = float(item["price"])
        if opened and category == "electronics":
            amount = amount * (1 - float(policy["restocking_fee_opened_electronics"]))
        if len(missing) > 0:
            amount = amount
        return {"method": "card", "amount_usd": round(amount + 1e-9, 2)}

    if days_since_delivery <= window + policy["store_credit_days_after_window"]:
        amount = float(item["price"])
        if opened and category == "electronics":
            amount = amount * (1 - float(policy["restocking_fee_opened_electronics"]))
        return {"method": "store_credit", "amount_usd": round(amount + 1e-9, 2)}

    return {"method": "decline", "amount_usd": 0}
