    def parse_date(s):
        y = int(s[0:4])
        m = int(s[5:7])
        d = int(s[8:10])
        return y, m, d

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def date_to_ordinal(s):
        y, m, d = parse_date(s)
        mdays = [31, 28 + (1 if is_leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = d
        i = 0
        while i < m - 1:
            total += mdays[i]
            i += 1
        y0 = 1
        while y0 < y:
            total += 366 if is_leap(y0) else 365
            y0 += 1
        return total

    def add_days(s, n):
        y, m, d = parse_date(s)
        mdays = [31, 28 + (1 if is_leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        d += n
        while True:
            lim = mdays[m - 1]
            if d <= lim:
                break
            d -= lim
            m += 1
            if m > 12:
                m = 1
                y += 1
                mdays = [31, 28 + (1 if is_leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return "%04d-%02d-%02d" % (y, m, d)

    def days_between(later, earlier):
        return date_to_ordinal(later) - date_to_ordinal(earlier)

    category = item["category"]
    window = policy["return_window_days"].get(category, 0)
    extra = policy["member_extra_days"] if customer["tier"] == "plus" else 0
    effective_window = window + extra

    requested_on = ret["requested_on"]
    delivered_on = order["delivered_on"]

    # Holiday return override
    dy, dm, dd = parse_date(delivered_on)
    ry, rm, rd = parse_date(requested_on)
    holiday_delivery = (dm == 11 and dd >= 15) or (dm == 12)
    holiday_end = "%04d-01-31" % (dy + 1)
    if holiday_delivery and date_to_ordinal(requested_on) <= date_to_ordinal(holiday_end):
        amount = float(item["price"])
        missing = ret["missing_accessories"]
        acc = item["accessories"]
        i = 0
        while i < len(missing):
            j = 0
            while j < len(acc):
                if acc[j]["name"] == missing[i]:
                    amount -= float(acc[j]["value"])
                    break
                j += 1
            i += 1
        if amount < 0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount, 2)}

    # Final sale and category-specific exclusions
    if item["final_sale"]:
        return {"method": "decline", "amount_usd": 0.0}

