    elif days_since_delivery <= effective_window + policy["store_credit_days_after_window"]:
        method = "store_credit"
    else:
        return {"method": "decline", "amount_usd": 0.0}

    amount = float(item["price"])

    if method == "card" and category == "electronics" and ret["opened"]:
