    req_y, req_m, req_d = to_ymd(requested_on)
    if req_y == y:
        req_idx = day_of_year(requested_on)
        if req_idx <= month_day_to_index(req_y, 1, 31):
            holiday_deadline = True

    if holiday_delivery and holiday_deadline:
        amount = round(float(item["price"]), 2)
        return {"method": "card", "amount_usd": amount}

    if item.get("final_sale", False):
        return {"method": "decline", "amount_usd": 0}

    if category == "beauty" and r["opened"]:
        return {"method": "decline", "amount_usd": 0}

    if not inside_window and not after_window_credit:
        return {"method": "decline", "amount_usd": 0}

    if category == "electronics" and r["opened"]:
        amount = float(item["price"]) * (1 - p["restocking_fee_opened_electronics"])
    else:
        amount = float(item["price"])

    if len(r["missing_accessories"]) > 0:
        accessories = item.get("accessories", [])
