def refund_decision(api, return_id: str) -> dict:
    r = api.read_return(return_id)
    o = api.read_order(r["order_id"])
    p = api.read_policy()
    customer = api.read_customer(o["customer_id"])

    def get_any(d, keys, default=None):
        if not isinstance(d, dict):
            return default
        for k in keys:
            if k in d:
                return d[k]
        return default

    def date_parts(s):
        parts = str(s).split("-")
        if len(parts) != 3:
            return None
        try:
            return int(parts[0]), int(parts[1]), int(parts[2])
        except Exception:
            return None

    def date_number(s):
        parts = date_parts(s)
        if parts is None:
            return None
        y, m, d = parts
        total = d
        for mm in range(1, m):
            if mm in [1, 3, 5, 7, 8, 10, 12]:
                total += 31
            elif mm in [4, 6, 9, 11]:
                total += 30
            else:
                leap = False
                if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0):
                    leap = True
                if leap:
                    total += 29
                else:
                    total += 28
        total += y * 366
        return total

    def same_year_delta(a, b):
        pa = date_parts(a)
        pb = date_parts(b)
        if pa is None or pb is None:
            return None
        ya, ma, da = pa
        yb, mb, db = pb
        if ya != yb:
            return None
        da0 = 0
        for mm in range(1, ma):
            if mm in [1, 3, 5, 7, 8, 10, 12]:
                da0 += 31
            elif mm in [4, 6, 9, 11]:
                da0 += 30
            else:
                leap = False
                if (ya % 4 == 0 and ya % 100 != 0) or (ya % 400 == 0):
                    leap = True
                if leap:
                    da0 += 29
                else:
                    da0 += 28
        db0 = 0
        for mm in range(1, mb):
            if mm in [1, 3, 5, 7, 8, 10, 12]:
                db0 += 31
            elif mm in [4, 6, 9, 11]:
                db0 += 30
            else:
                leap = False
                if (yb % 4 == 0 and yb % 100 != 0) or (yb % 400 == 0):
                    leap = True
                if leap:
                    db0 += 29
                else:
                    db0 += 28
        return (db0 + db) - (da0 + da)

    item_key = get_any(r, ["sku", "item_sku", "item_id", "id"], None)
    item = None
    for it in o["items"]:
        if get_any(it, ["sku", "item_sku", "item_id", "id"], None) == item_key:
            item = it
            break
    if item is None:
        if len(o["items"]) == 1:
            item = o["items"][0]
        else:
            return {"method": "decline", "amount_usd": 0}

    tier = ""
    if isinstance(customer, dict):
        tier = get_any(customer, ["tier"], "")

    delivered = get_any(o, ["delivered_on", "delivered_date"], "")
    requested = get_any(r, ["requested_on", "requested_date"], "")

    category = get_any(item, ["category"], "")
    return_windows = get_any(p, ["return_window_days", "return_window_days_by_category"], {})
    base_window = 0
    if isinstance(return_windows, dict):
        base_window = int(get_any(return_windows, [category], 0))
    if tier == "plus":
        base_window += int(get_any(p, ["member_extra_days"], 0))

    dp = date_parts(delivered)
    rp = date_parts(requested)

    holiday = False
    if dp is not None and rp is not None:
        yd, md, dd = dp
        yr, mr, dr = rp
        if yr == yd + 1 and mr == 1 and dr <= 31:
            if (md == 11 and dd >= 15) or md == 12:
                holiday = True

    reason = get_any(r, ["reason"], "")
    if reason == "damaged":
        amount = float(get_any(item, ["price"], 0)) + float(get_any(item, ["shipping"], 0))
        dn = date_number(delivered)
        rn = date_number(requested)
        if dn is not None and rn is not None and rn - dn <= 90:
            return {"method": "card", "amount_usd": round(amount, 2)}
        return {"method": "decline", "amount_usd": 0}

    if get_any(item, ["final_sale"], False):
        return {"method": "decline", "amount_usd": 0}

    if category == "beauty" and get_any(r, ["opened"], False):
        return {"method": "decline", "amount_usd": 0}

    amount = float(get_any(item, ["price"], 0))
    method = "card"

    if not holiday:
        delta = same_year_delta(delivered, requested)
        if delta is None or delta < 0:
            return {"method": "decline", "amount_usd": 0}

        after_close = base_window + int(get_any(p, ["store_credit_days_after_window"], 0))
        if delta <= base_window:
            method = "card"
        elif delta <= after_close:
            method = "store_credit"
        else:
            return {"method": "decline", "amount_usd": 0}

        if category == "electronics" and get_any(r, ["opened"], False):
            amount = amount - (float(get_any(item, ["price"], 0)) * float(get_any(p, ["restocking_fee_opened_electronics"], 0)))

    missing = get_any(r, ["missing_accessories"], [])
    if not isinstance(missing, list):
        missing = []
    accs = get_any(item, ["accessories"], [])
    if not isinstance(accs, list):
        accs = []
    for acc in accs:
        name = get_any(acc, ["name"], None)
        if name in missing:
            amount = amount - float(get_any(acc, ["value"], 0))

    amount = round(amount, 2)
    if amount < 0:
        amount = 0.0

    return {"method": method, "amount_usd": amount}
