            total_meals = 0.0
            for r in meals:
                total_meals += float(r["amount"]) * float(rates[r["currency"]])
            if total_meals > float(allowances["meals_per_day"]):
                reimb = float(allowances["meals_per_day"])
            else:
                reimb = total_meals
            days[days.index(d)] = (d, reimb)
        else:
            days[days.index(d)] = (d, 0.0)

    for r in receipts:
        if r["category"] == "hotel":
            note = r["note"].lower()
            if "alcohol" in note:
