def refund_decision(api, return_id: str) -> dict:
    r = api.read_return(return_id)
    o = api.read_order(r["order_id"])
    p = api.read_policy()
    c = api.read_customer(o["customer_id"])

    sku = r["sku"]
    item = None
    for x in o["items"]:
        if x["sku"] == sku:
            item = x
            break

    if item is None:
        return {"method": "decline", "amount_usd": 0}

    requested_on = r["requested_on"]
    delivered_on = o["delivered_on"]

    # Parse dates as YYYY-MM-DD
    ry = int(requested_on[0:4])
    rm = int(requested_on[5:7])
    rd = int(requested_on[8:10])
    dy = int(delivered_on[0:4])
    dm = int(delivered_on[5:7])
    dd = int(delivered_on[8:10])

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_before_month(y, m):
        d = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        n = d[m - 1]
        if m > 2 and is_leap(y):
            n += 1
        return n

    def days_since_epoch(y, m, d):
        y1 = y - 1
        return 365 * y1 + y1 // 4 - y1 // 100 + y1 // 400 + days_before_month(y, m) + d

    requested_days = days_since_epoch(ry, rm, rd)
    delivered_days = days_since_epoch(dy, dm, dd)
    age_days = requested_days - delivered_days

    category = item["category"]
    window = p["return_window_days"][category]
    if c["tier"] == "plus":
        window += p["member_extra_days"]

    holiday = False
    if (dm == 11 and dd >= 15) or dm == 12 or (dm == 1 and dd <= 31):
        holiday = True
        if dm == 11 and dd < 15:
            holiday = False

    final_sale = bool(item["final_sale"])
    opened = bool(r["opened"])
    missing = r["missing_accessories"]

    damaged = False
    reason = r["reason"]
    if reason == "damaged":
        damaged = True

    if damaged and age_days <= p["damaged_refund_days"]:
        amount = float(item["price"]) + float(item["shipping"])
        amount = round(amount, 2)
        return api.issue_refund({"return_id": return_id, "amount_usd": amount, "method": "card"})

    if final_sale:
        return api.decline_return({"return_id": return_id})

    if category == "beauty" and opened:
        return api.decline_return({"return_id": return_id})

    if age_days <= window:
        method = "card"
    elif age_days <= window + p["store_credit_days_after_window"]:
        method = "store_credit"
    else:
        return api.decline_return({"return_id": return_id})

    amount = float(item["price"])

    if category == "electronics" and opened:
        amount = amount - amount * float(p["restocking_fee_opened_electronics"])

    if holiday and method == "card":
        pass
    elif category == "electronics" and opened:
        pass

    accessory_values = 0.0
    if item["accessories"]:
        for acc in item["accessories"]:
            found = False
            for name in missing:
                if name == acc["name"]:
                    found = True
                    break
            if found:
                accessory_values += float(acc["value"])
    amount -= accessory_values

    if amount < 0:
        amount = 0.0

    amount = round(amount, 2)
    return api.issue_refund({"return_id": return_id, "amount_usd": amount, "method": method})
