    missing_accessories = r.get("missing_accessories", [])
    requested_on = r.get("requested_on", "")

    category = item.get("category", "")
    window = policy.get("return_window_days", {}).get(category, 0)
    if is_member:
        window += policy.get("member_extra_days", 0)

    ordered_on = order.get("ordered_on", "")
