        for mm in range(1, m):
            n += dim(y, mm)
        n += d
        return n

    def date_diff(a, b):
        ay, am, ad = to_ymd(a)
        by, bm, bd = to_ymd(b)
        return days_from_ymd(by, bm, bd) - days_from_ymd(ay, am, ad)

    def month_day(s):
        p = s.split("-")
        return int(p[1]), int(p[2])

    days_since_delivery = date_diff(delivered_on, requested_on)
    holiday = False
    md = month_day(delivered_on)
    if (md[0] == 11 and md[1] >= 15) or md[0] == 12:
        holiday = True
        if month_day(requested_on)[0] == 1 and month_day(requested_on)[1] <= 31:
            holiday = True

    damaged = "damaged" in reason.lower()

    if item.get("final_sale", False):
