        y, m, d = to_date(s)
        while n > 0:
            dim = days_in_month(y, m)
            rem = dim - d
            if n <= rem:
                d += n
                n = 0
            else:
                n -= rem + 1
                d = 1
                m += 1
                if m > 12:
                    m = 1
                    y += 1
        return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)

    def between(a, x, b):
        return a <= x and x <= b

    delivered_y, delivered_m, delivered_d = to_date(delivered)
    requested_y, requested_m, requested_d = to_date(requested)

