    def ymd(s):
        parts = s.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def days_from_ymd(s):
        y, m, d = ymd(s)
        leap = y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
        month_days = [31, 28 + (1 if leap else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        n = 0
        i = 0
        while i < m - 1:
            n += month_days[i]
            i += 1
        return y * 365 + y // 4 - y // 100 + y // 400 + n + d

    def diff_days(a, b):
        return days_from_ymd(a) - days_from_ymd(b)

