        amount = price
        amount -= sum([float(x["value"]) for x in item["accessories"] if x["name"] in missing])
        if amount < 0:
            amount = 0.0
        amount = round(amount, 2)
        api.issue_refund({"return_id": return_id, "amount_usd": amount, "method": "card"})
        return {"method": "card", "amount_usd": amount}

    if days_after_delivery <= window:
        method = "card"
    elif days_after_delivery <= window + policy["store_credit_days_after_window"]:
        method = "store_credit"
    else:
        api.decline_return(return_id)
        return {"method": "decline", "amount_usd": 0.0}

    amount = price
