    if damaged_reason:
        damaged_days = int(policy.get("damaged_refund_days", 0)) if isinstance(policy, dict) else 0
        if days_since_delivery <= damaged_days:
            amount = round(price + shipping, 2)
            try:
                api.issue_refund({"return_id": return_id, "amount_usd": amount, "method": "card"})
            except Exception:
                try:
                    api.issue_refund(return_id, amount, "card")
                except Exception:
                    pass
            return {"method": "card", "amount_usd": amount}

    method = "card"
    if not holiday:
        after_window = days_since_delivery - window_days
        store_credit_days_after_window = int(policy.get("store_credit_days_after_window", 0)) if isinstance(policy, dict) else 0
        if after_window > store_credit_days_after_window:
            try:
                api.decline_return(return_id)
            except Exception:
                pass
            return {"method": "decline", "amount_usd": 0.0}
        if after_window > 0:
            method = "store_credit"

    amount = price
    if holiday:
        method = "card"

    if opened and category == "electronics" and not holiday:
        fee = 0.0
        if isinstance(policy, dict):
