        amount = amount - (price * fee)

    accessories = item.get("accessories", [])
    if isinstance(accessories, list) and isinstance(missing, list):
        for acc in accessories:
            if isinstance(acc, dict):
                name = acc.get("name")
                if any(name == m for m in missing):
                    amount = amount - float(acc.get("value", 0.0))

    if holiday:
        amount = price
        method = "card"

    amount = round(amount, 2)
    if amount < 0:
        amount = 0.0

    try:
        api.issue_refund({"return_id": return_id, "amount_usd": amount, "method": method})
    except Exception:
